mapper.select:
SELECT COUNT(*)
FROM notification_log
WHERE receiver_user_id = #{studentId}

mapper.sql:
WHERE 1 = 1

    AND (
        receiver_name LIKE CONCAT('%', #{query.keyword}, '%')
        OR phone LIKE CONCAT('%', #{query.keyword}, '%')
        OR title LIKE CONCAT('%', #{query.keyword}, '%')
        OR content LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND notify_type = #{query.notifyType}


    AND send_status = #{query.sendStatus}


    AND send_time >= #{query.startTime}


    AND send_time <= #{query.endTime}
